import cv2 as cv
import numpy as np

def solve(img):
    # Flip the image horizontally
    flipped_img = cv.flip(img, 1)

    # Convert to grayscale
    gray = cv.cvtColor(flipped_img, cv.COLOR_BGR2GRAY)

    # Find object outlines
    contours, _ = cv.findContours(gray, cv.RETR_EXTERNAL, cv.CHAIN_APPROX_SIMPLE)
    contours = [c for c in contours if cv.contourArea(c) >= 100]

    # Count the number of pixels whose grayscale value changed
    changed_pixels = 0
    for i, c in enumerate(contours, 1):
        x, y, w, h = cv.boundingRect(c)
        for x in range(x, x + w):
            for y in range(y, y + h):
                if gray[x, y] != gray[x, y + 1]:
                    changed_pixels += 1
                if gray[x, y] != gray[x + 1, y]:
                    changed_pixels += 1
                if gray[x, y] != gray[x + 1, y + 1]:
                    changed_pixels += 1

    return changed_pixels
